query:
NODE VALUE `inDegreeSum` SumAgg<INT64> = 0
TABLE `totals` TYPED TABLE { `id` STRING, `total` INT64 }

MATCH (`src`:`player`)-[`e`:`follow`]->(`dst`:`player`)
PER PATH {
  SET `dst`.@`inDegreeSum` += coalesce(`e`.`degree`, 0)
}

MATCH (`p`:`player`)
PER NODE (`p`) {
  EXPORT `p`.`id` AS `id`, `p`.@`inDegreeSum` AS `total` INTO `totals`
}

FOR `r` IN `totals`
RETURN `r`.`id` AS `id`, `r`.`total` AS `total`
